async () => {
  // Try to access the SuperTokens instance and check its config
  // Look for any global st instance
  const stKeys = Object.keys(window).filter(k => k.toLowerCase().includes('supertok') || k.toLowerCase().includes('__st'));
  // Also try to inspect Network: re-run a sign-in-equivalent call and grab response headers
  const r = await fetch('/raven/auth/session/refresh', {
    method: 'POST',
    headers: { 
      'st-auth-mode': 'header', 
      'rid': 'session',
      'fdi-version': '3.0',
      // Include Authorization header with a fake bearer to trigger header-mode path on server
      'Authorization': 'Bearer noop',
    },
    credentials: 'omit', // Don't send cookies, force the backend to make a fresh decision
  });
  const set_cookie = r.headers.get('set-cookie'); // browsers typically don't expose this
  const front_token = r.headers.get('front-token');
  const at_header = r.headers.get('st-access-token');
  const headers = {};
  r.headers.forEach((v, k) => { headers[k] = v.length > 80 ? v.slice(0,60) + '...' : v; });
  return {
    st_window_keys: stKeys,
    refresh_status: r.status,
    front_token,
    st_access_token_header: at_header,
    all_headers: headers,
  };
}

