  const base = `/raven/api/v1/orgs/${orgId}/workspaces/${wsId}/knowledge-bases/${kbId}`;

  // 1) URL source — exercises the source_type:'web_page' fix
  const urlRes = await fetch(`${base}/sources`, {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ source_type: 'web_page', url: 'https://example.com/' }),
  });
  const urlBody = urlRes.ok ? await urlRes.json() : await urlRes.text();

  // 2) Document upload
  const fileContent = new Blob(['# End-to-end Smoke Test\n\nUploaded at ' + new Date().toISOString()], { type: 'text/markdown' });
  const file = new File([fileContent], 'e2e-smoke.md', { type: 'text/markdown' });
  const fd = new FormData();
  fd.append('file', file);
  const upRes = await fetch(`${base}/documents/upload`, { method: 'POST', credentials: 'include', body: fd });
  const upBody = upRes.ok ? await upRes.json() : await upRes.text();

  // 3) Re-list sources + documents to confirm landed
  const sList = await fetch(`${base}/sources`, { credentials: 'include' });
  const dList = await fetch(`${base}/documents`, { credentials: 'include' });
  const sources = sList.ok ? await sList.json() : await sList.text();
  const documents = dList.ok ? await dList.json() : await dList.text();

  return {
    url_source: { status: urlRes.status, body: urlBody },
    upload: { status: upRes.status, body: upBody },
    list: {
      sources: Array.isArray(sources) ? sources.map(s => ({ url: s.url, status: s.status })) : sources,
      documents: Array.isArray(documents) ? documents.map(d => ({ name: d.name || d.file_name, status: d.status || d.processing_status })) : documents,
    },
  };
}

